<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({campaigns:[],consents:[],touchEvents:[]}),msg=ref('');const revenue=computed(()=>data.value.touchEvents.reduce((n,x)=>n+x.revenue,0));async function load(){try{data.value=await request('/api/marketing-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/marketing-ops/audiences',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',segmentCode:'SEG-'+Date.now(),name:'高意向制造企业',ruleExpression:'industry=manufacturing AND intentScore>=60',estimatedSize:1200})});msg.value='动态受众已创建，可继续编排活动旅程';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>GROWTH AUTOMATION</small><h3>营销增长编排中心</h3><p>用动态分群、合规同意和行为旅程连接获客与收入。</p></div><button @click="create">创建动态受众</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>活动组合</span><b>{{data.campaigns.length}}</b><small>草稿、审批与运行</small></article><article><span>有效同意</span><b>{{data.consents.filter(x=>x.status==='GRANTED').length}}</b><small>按联系人和渠道</small></article><article><span>归因收入</span><b>¥{{revenue.toLocaleString()}}</b><small>触点关联收入</small></article></section><section class="board"><article><header><h4>营销活动</h4><button @click="load">刷新</button></header><div class="line" v-for="x in data.campaigns" :key="x.id"><div><b>{{x.name}}</b><small>{{x.campaignNo}} · {{x.channel}} · ¥{{x.budget.toLocaleString()}}</small></div><em>{{x.status}}</em></div><p v-if="!data.campaigns.length">暂无专业营销活动。</p></article><article><header><h4>最近客户触点</h4><span>合规校验已启用</span></header><div class="line" v-for="x in data.touchEvents" :key="x.id"><div><b>{{x.eventType}}</b><small>{{x.contactKey}} · 评分 +{{x.scoreDelta}}</small></div><em>{{x.eventId}}</em></div><p v-if="!data.touchEvents.length">触达后将在这里形成可归因事件。</p></article></section></template>
<style scoped>.head{padding:27px 30px;border-radius:14px;color:white;background:#30234c;display:flex;align-items:end;justify-content:space-between}.head small{letter-spacing:1.5px;color:#cabee0}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#dcd4e9}.head button{border:0;border-radius:8px;background:#f0b85f;padding:11px 17px;color:#30234c;font-weight:700}.msg{padding:10px 14px;background:#f7f3fc;border-left:3px solid #7657a5}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #e6e0ee;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#766d82}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.line{display:flex;justify-content:space-between;align-items:center}.board header{padding-bottom:12px;border-bottom:1px solid #eee9f3}.board header button{border:0;background:transparent;color:#6d4d99}.line{padding:14px 0;border-bottom:1px solid #f0ecf4}.line small{display:block;color:#82778e;margin-top:4px}.line em{font-style:normal;font-size:12px;color:#6d4d99}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
